document.addEventListener('DOMContentLoaded', function() {
const mainHeader = document.getElementById('main-header');
const headerSpacer = document.getElementById('header-spacer');
const stickyNav = document.getElementById('sticky-nav');
const navInner = document.getElementById('nav-inner');
const navSpacer = document.getElementById('nav-spacer');
const scrollIcon = document.getElementById('scroll-icon');
const mobileMenuBtn = document.getElementById('mobile-menu-btn');
const mobileMenu = document.getElementById('mobile-menu');
const menuIcon = document.getElementById('menu-icon');
const closeIcon = document.getElementById('close-icon');

let isScrolled = false;
let mobileSticky = true;

// Hysteresis thresholds to prevent flickering at the boundary
const SCROLL_DOWN_THRESHOLD = 180; // Collapse header when scrolling past this
const SCROLL_UP_THRESHOLD = 120; // Restore header when scrolling above this

function handleScroll() {
const scrollY = window.scrollY;

// Use hysteresis: different thresholds for scrolling down vs up
let shouldBeScrolled;
if (isScrolled) {
// Currently collapsed - only restore if we scroll well above the threshold
shouldBeScrolled = scrollY > SCROLL_UP_THRESHOLD;
} else {
// Currently expanded - only collapse if we scroll past the threshold
shouldBeScrolled = scrollY > SCROLL_DOWN_THRESHOLD;
}

// Mobile sticky logic
const firstImage = document.querySelector('main img, .featured-image, article img');
if (firstImage) {
const imageRect = firstImage.getBoundingClientRect();
const imageBottom = imageRect.bottom + scrollY;
mobileSticky = scrollY < imageBottom - 48;
}

if (shouldBeScrolled !== isScrolled) {
isScrolled = shouldBeScrolled;

// Signal for header-anchored fixed overlays (newsletter / Vera slide-in
// bar). Collapsed => header is the 48px sticky nav; expanded => full
// 145px header. The bars read this to sit right below the menu.
document.documentElement.classList.toggle('cb-header-collapsed', isScrolled);

if (isScrolled) {
headerSpacer.classList.remove('h-1');
headerSpacer.classList.add('h-0');
mainHeader.classList.remove('h-24', 'opacity-100');
mainHeader.classList.add('h-0', 'opacity-0');

stickyNav.classList.add('md:fixed', 'md:top-0', 'md:left-0', 'md:right-0', 'md:z-50');
